mapper.select:
SELECT auth_seq, auth_approach, user_mst_seq,
       create_user, create_at, update_user, update_at, del_yn, note
FROM utb_user_social_mapp
WHERE auth_approach = #{authApproach}
  AND auth_seq = #{authSeq}
  AND del_yn = 'N'

mapper.update:
UPDATE utb_user_social
SET auth_token = #{authToken},
    update_at = CURRENT_TIMESTAMP
WHERE auth_approach = #{authApproach}
  AND auth_seq = #{authSeq}
